text:
Here is a sample program that demonstrates complex.

// Demonstrate complex.
#include <iostream>
#include <complex>
using namespace std;
int main()
{
complex<double> cmpx1(1, 0);
complex<double> cmpx2(1, 1);
cout << cmpx1 << " " << cmpx2 << endl;
complex<double> cmpx3 = cmpx1 + cmpx2;
cout << cmpx3 << endl;
cmpx3 += 10;
cout << cmpx3 << endl;
return 0;
}

Its output is shown here: (1,0) (1,1) (2,1) (12,1) 900 Function Description template <class T>

