#include <iostream>
#include <vector>
#include <numeric>
using namespace std;
int main()
{
vector<int> v(5), r(5);
int i;
for(i=0; i<5; i++) v[i] = i;
cout << "Original sequence: ";
for(i=0; i<5; i++)
cout << v[i] << " ";
cout << endl;
partial_sum(v.begin(), v.end(), r.begin());
cout << "Resulting sequence: ";
for(i=0; i<5; i++)
cout << r[i] << " ";
return 0;
}

