#include "str.h"
#include <iostream>
#include <fstream>
using namespace std;
// executable file extensions

char ext[3][4] = { "EXE", "COM", "BAT"

};

text:
int main(int argc, char *argv[])
{
StrType fname;
int i;
if(argc!=2) {
cout << "Usage: fname\n";
return 1;
}
fname = argv[1];
fname = fname + "."; // add period
for(i=0; i<3; i++) {
fname = fname + ext[i]; // add extension
cout << "Trying " << fname << " ";
ifstream f(fname);
if(f) {
cout << "- Exists\n";
f.close();
}
else cout << "- Not found\n";
fname = fname - ext[i]; // subtract extension
}
return 0;
}

